import{_ as a,o as s,c as o,a2 as t}from"./chunks/framework.BG8d4IEm.js";const n="/assets/2019-05-11-tab.DFBeogEF.png",g=JSON.parse('{"title":"转义字符 \\\\t","description":"","frontmatter":{"tags":["计算机基础","编码"]},"headers":[],"relativePath":"posts/2019-05-11-escape.md","filePath":"posts/2019-05-11-escape.md"}'),c={name:"posts/2019-05-11-escape.md"};function p(r,e,l,d,i,b){return s(),o("div",null,[...e[0]||(e[0]=[t(`<h1 id="转义字符-t" tabindex="-1">转义字符 \\t <a class="header-anchor" href="#转义字符-t" aria-label="Permalink to &quot;转义字符 \\t&quot;">​</a></h1><p><strong>转义字符 \\t</strong></p><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>在学习 <a href="https://book.douban.com/subject/1139336/" target="_blank" rel="noreferrer">c 程序设计语言第二版</a> 时,无法理解习题 1.20 <strong>制表符终止位</strong> 的概念,查阅相关资料,发现是未理解转义字符 <code>\\t</code></p><h2 id="制表符-tab" tabindex="-1">制表符(TAB) <a class="header-anchor" href="#制表符-tab" aria-label="Permalink to &quot;制表符(TAB)&quot;">​</a></h2><p><code>\\t</code> 制表符用于控制水平光标位置。 在终端默认为 8 个字符,制表符的特性总结为:<strong>将当前光标自动移动到,距离最近的下一个8n字符间隔之后,n 为正整数</strong></p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>8 个<strong>字符间隔</strong>是默认行为,可用 <code>tabs n</code> 设定 <code>\\t</code> 的间距 ,<strong>字符间隔</strong>为单个空格宽度 ,若为中文等其他字符可能占据多个<strong>字符间隔</strong></p></div><p>而之前的错误认知一直以为制表符，代替固定的<strong>字符间隔</strong>,例如 <code>\\t</code> 表示 3 个<strong>字符间隔</strong>可以采用如下方式验证</p><p>shell 中输入如下指令</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;"># 在出现 \\t 的位置后利用 | 标识</span></span>
<span class="line"><span style="color:#79B8FF;">echo</span><span style="color:#9ECBFF;"> &quot;hello--\\t|中aa\\t|\\t|\\na\\t|----\\t|------\\t|&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>在 <code>\\t</code> 后填充 <code>|</code> 字符模拟光标位置,输出结果为:</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span>hello-- |中aa   |       |</span></span>
<span class="line"><span>a       |----   |------ |</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>结果可知 <code>\\t</code> 会自动调整光标位置,使之在 8n 个<strong>字符间隔</strong>之后</p><p>也可以在 <code>vscode</code> 编辑其中验证此特性,输入一个或多个字符按一下 <code>tab</code> 键看光标会移动到哪？</p><blockquote><p>注意编辑器中查看 <code>tab</code> 相关设置,确定使能了制表符特性</p></blockquote><p>实际上在文档软件中也存在制表符概念,这里以 mac 自带的 pages 举例。 参看动图:</p><p><img src="`+n+'" alt="" loading="lazy"></p><p>可以看到,在按下 <code>tab</code> 键后,光标的自动移动到,布局中设定的制表符距离之后。</p><p>通过修改距离,会更改光标的移动间距,读者可以尝试输入字符再按 tab 键,确认光标移动是否符合如下规则</p><blockquote><p>光标只会相对每行起始位置,移动到最近 <code>xn</code> 间距后,<code>x</code> 表示设定的距离,<code>n</code> 为正整数</p></blockquote><p>通过上述示例希望读者完全理解 <code>\\t</code> 的作用。</p><p>此外推荐阅读 <a href="https://www.ruanyifeng.com/blog/2006/04/post_213.html" target="_blank" rel="noreferrer">阮一峰回车和换行符</a> 理解 <code>\\r</code> 和 <code>\\n</code></p><p>既然理解了制表符的功能制表符终止位的含义就清晰可见了</p><blockquote><p><strong>制表符终止位是指使用制表符键所对应的光标位置</strong></p></blockquote>',24)])])}const h=a(c,[["render",p]]);export{g as __pageData,h as default};
